func runBuy(cmd *cobra.Command, flags *rootFlags, query string, qty int, sourceFlag string) error {
	sku := normalizeBuySKU(query)
	if sku == "" {
		return usageErr(fmt.Errorf("could not identify a SKU in %q", query))
	}

	buySources, err := resolveBuySources(sourceFlag, sku)
	if err != nil {
		return usageErr(err)
	}

	httpClient := &http.Client{Timeout: flags.timeout}
	fetchedAt := time.Now().UTC().Format(time.RFC3339)

	searchResults, searchErrs := cliutil.FanoutRun(
		cmd.Context(),
		buySources.SearchSources,
		func(sourceName string) string { return sourceName },
		func(ctx context.Context, sourceName string) ([]buyOffer, error) {
			return fetchBuySearchOffers(ctx, httpClient, sourceName, sku, qty, fetchedAt)
		},
		cliutil.WithConcurrency(minInt(len(buySources.SearchSources), 8)),
	)

	pageResults, pageErrs := cliutil.FanoutRun(
		cmd.Context(),
		buySources.Retailers,
		func(r buyRetailer) string { return r.Name },
		func(ctx context.Context, r buyRetailer) (buyOffer, error) {
			return fetchBuyOffer(ctx, httpClient, r, sku, qty, fetchedAt)
		},
		cliutil.WithConcurrency(minInt(len(buySources.Retailers), 6)),
	)

	offers := make([]buyOffer, 0, len(searchResults)+len(pageResults))
	for _, result := range searchResults {
		offers = mergeBuyOffers(offers, result.Value)
	}
	for _, result := range pageResults {
		offers = mergeBuyOffers(offers, []buyOffer{result.Value})
	}

	sort.SliceStable(offers, func(i, j int) bool {
		if offers[i].Price == 0 {
			return false
		}
		if offers[j].Price == 0 {
			return true
		}
		if offers[i].Subtotal == offers[j].Subtotal {
			return offers[i].Source < offers[j].Source
		}
		return offers[i].Subtotal < offers[j].Subtotal
	})

	failures := make([]buyFailure, 0, len(searchErrs)+len(pageErrs))
	for _, e := range searchErrs {
		failures = append(failures, buyFailure{Source: e.Source, Reason: shortFanoutErrMsg(e.Err)})
	}
	for _, e := range pageErrs {
		failures = append(failures, buyFailure{Source: e.Source, Reason: shortFanoutErrMsg(e.Err)})
	}
	failures = filterBuyFailuresWithOffers(failures, offers)

	var best *buyOffer
	for i := range offers {
		if offers[i].Price > 0 {
			best = &offers[i]
			break
		}
	}

	result := buyResult{
		Query:       query,
		SKU:         sku,
		Quantity:    qty,
		Best:        best,
		Offers:      offers,
		Failures:    failures,
		Sources:     buySources.Names,
		GeneratedAt: fetchedAt,
		Assumptions: []string{
			"Subtotal excludes tax, shipping, coupons, membership pricing, and store-card promotions unless the retailer exposes them on the public page.",
			"Exact-SKU matching accepts common retail suffixes such as -R and wallplate bundle aliases such as DVRFW-6L-WH.",
			"Active-source search results are used only when the normalized source identifier, title, description, or URL contains the exact normalized SKU.",
		},
	}

	if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
		return printJSONFiltered(cmd.OutOrStdout(), result, flags)
	}
	if flags.csv {
		return printBuyCSV(cmd.OutOrStdout(), result)
	}
	return printBuyTable(cmd.OutOrStdout(), result)
}

