func resolveBuySources(sourceFlag, sku string) (buySourceSet, error) {
	retailers := buyRetailersForSKU(sku)
	searchSources := buySearchSourcesForSKU(sku)
	if sourceFlag == "" {
		return buySourceSet{
			Retailers:     retailers,
			SearchSources: searchSources,
			Names:         uniqueSortedBuySourceNames(searchSources, retailers),
		}, nil
	}

	retailerByName := map[string]buyRetailer{}
	for _, r := range retailers {
		retailerByName[r.Name] = r
	}
	activeByName := map[string]bool{}
	for _, s := range activeSources() {
		activeByName[s.Name] = true
	}

	var selectedRetailers []buyRetailer
	var selectedSearchSources []string
	for _, name := range splitCSV(sourceFlag) {
		added := false
		if r, ok := retailerByName[name]; ok {
			selectedRetailers = append(selectedRetailers, r)
			added = true
		}
		if activeByName[name] {
			selectedSearchSources = append(selectedSearchSources, name)
			added = true
		}
		if !added {
			return buySourceSet{}, fmt.Errorf("unknown source %q; valid sources: %s", name, strings.Join(validBuySourceNames(sku), ", "))
		}
	}
	return buySourceSet{
		Retailers:     selectedRetailers,
		SearchSources: selectedSearchSources,
		Names:         uniqueSortedBuySourceNames(selectedSearchSources, selectedRetailers),
	}, nil
}

